                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <label className="block text-xs font-semibold text-muted-foreground font-arabic mb-1.5">الرقم الضريبي (إن وجد)</label>
